  var eq = typeof d.equity === "number" ? d.equity : start, scale = c / start;
  var R = { kind: kind, cap: c, start: start, scale: scale, paperEq: eq, paperPnl: eq - start, realPnl: (eq - start) * scale, rows: [], reasons: [], notes: [], est: [], checks: { n: 0, below: 0, unknown: 0, ex: [] }, conc: null };
  R.realEq = c + R.realPnl; R.ret = R.realPnl / c;
  var cs = curveScan(d.curve, start, scale, c); R.minEq = Math.min(cs.min, R.realEq); R.bust = cs.bust; R.dd = cs.dd;
  if (R.bust === null && R.realEq <= 0) R.bust = d.ts || 0;
  function chk(label, have, need, est) {
    R.checks.n++;
    if (!need) { R.checks.unknown++; return; }
    if (need.est || est) R.est.push("minimum u " + label + " bez ceny → jen minimální hodnota objednávky");
    if (have + 1e-9 < need.usd) { R.checks.below++; if (R.checks.ex.length < 5) R.checks.ex.push(label + ": " + usd(have) + " < min " + usd(need.usd)); }
  }
