  if (R.bust !== null) { R.verdict = "no"; R.reasons.unshift("kapitál " + usd(c, 0) + " by došel" + (R.bust ? " " + dPr(R.bust) + " (Praha)" : "") + " – další obchody už by nešly"); }
  else if (ch.n && ch.below / ch.n >= 0.5) R.verdict = "no";
  else if (ch.below || R.reasons.length || ch.unknown) R.verdict = "part";
