  h += '<div class="rc-v rc-v-' + R.verdict + '">' + VTXT[R.verdict] + " při " + R.cap + ' $ <span class="rc-n">· výsledek ' + (res >= 0 ? "zisk" : "ztráta") + " " + sg(res) + " (" + pc(R.ret) + ")</span></div>";
  h += '<div class="rc-k"><div><span>Paper start → reálně</span><b>' + usd(R.start, 0) + " → " + usd(R.cap, 0) + "</b><i>měřítko ×" + nf(R.scale, 3) + "</i></div>";
  h += "<div><span>P&amp;L paper</span><b class='" + cl(R.paperPnl) + "'>" + sg(R.paperPnl) + "</b><i>equity " + usd(R.paperEq) + "</i></div>";
  h += "<div><span>P&amp;L reálně</span><b class='" + cl(res) + "'>" + sg(res) + "</b><i>equity " + usd(R.realEq) + "</i></div>";
  h += "<div><span>Nejnižší equity reálně</span><b class='" + (R.minEq <= 0 ? "rc-dn" : "") + "'>" + usd(R.minEq) + "</b><i>max pokles " + nf(R.dd * 100, 0) + " %</i></div></div>";
