  if (R.checks.ex.length) h += '<div class="rc-n">nešlo by provést: ' + R.checks.ex.map(esc).join(" · ") + "</div>";
  h += '<table class="rc-t">' + R.rows.map(function (r) { return "<tr><td>" + esc(r[0]) + "</td><td>" + r[1] + "</td></tr>"; }).join("") + "</table>";
  if (R.checks.n) h += '<div class="rc-n">Kontrola minim: ' + R.checks.n + " obchodů/trhů · pod minimem " + R.checks.below + (R.checks.unknown ? " · neznámé " + R.checks.unknown : "") + "</div>";
