  ".rc-up{color:#2ee59d}.rc-dn{color:#ff5d73}.rc-r{margin:6px 0 6px 18px;padding:0}.rc-r li{margin:2px 0}.rc-t{width:100%;border-collapse:collapse;margin:6px 0;font-size:12.5px}.rc-t td{padding:4px 6px;border-bottom:1px solid rgba(138,106,32,.3);vertical-align:top}.rc-t td:first-child{opacity:.75;width:42%}.rc-n{font-size:11.5px;opacity:.75;margin-top:5px}";
function injectCss() { if (!root.document || root.document.getElementById("rc-css")) return; var st = root.document.createElement("style"); st.id = "rc-css"; st.textContent = CSS; (root.document.head || root.document.documentElement).appendChild(st); }
